package org.strongswan.android.rookstride;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class PairReuseTest {
 private Gateway node(String host)throws Exception{Gateway n=new Gateway();n.set("host",host);n.set("admin","root");n.set("fingerprint","SHA256:fixture");n.set("machine",host);n.sshPassword="fixture-password";n.data.put("remember",true);return n;}
 @Test public void aPairHasTwoPhysicalServerCardsWithTheirRoles()throws Exception{Gateway a=node("entry.example.net"),b=node("exit.example.net");a.exit=b;ArrayList<Gateway> records=new ArrayList<>(Arrays.asList(a));assertEquals(2,PairNodes.catalog(records).size());assertSame(a,PairNodes.owner(records,b));assertEquals("entry",PairNodes.role(a,a));assertEquals("exit",PairNodes.role(a,b));assertSame(b,PairNodes.find(records,b.get("id")));}
 @Test public void aNewPairReusesBothSavedIdentitiesAndCredentialsWithoutDuplicateServers()throws Exception{Gateway a=node("a.example.net"),b=node("b.example.net"),other=node("other.example.net");a.set("protocol","awg");b.set("protocol","");Gateway pair=PairNodes.copy(a);pair.exit=PairNodes.copy(b);ArrayList<Gateway> records=new ArrayList<>(Arrays.asList(a,b,other));PairNodes.attach(records,pair);assertEquals(2,records.size());assertEquals(3,PairNodes.catalog(records).size());assertEquals(a.get("id"),pair.get("id"));assertEquals("fixture-password",pair.sshPassword);assertEquals(b.get("fingerprint"),pair.exit.get("fingerprint"));assertSame(other,records.get(0));}
 @Test public void changedFingerprintsNeverMakeTwoEndpointsEquivalent()throws Exception{Gateway a=node("vpn.example.net"),b=node("vpn.example.net");b.set("fingerprint","SHA256:changed");assertFalse(PairNodes.same(a,b));}
 @Test public void copyingAndChangingRolesDoesNotMutateTheExistingPair()throws Exception{Gateway a=node("a.example.net"),b=node("b.example.net");a.exit=b;Gateway x=PairNodes.copy(b),y=PairNodes.copy(a);x.exit=y;x.set("protocol","xray");assertSame(b,a.exit);assertNull(y.exit);assertEquals("fixture-password",y.sshPassword);}
 @Test public void replacingOnePartKeepsTheUnselectedPartnerAsAManagedServer()throws Exception{Gateway a=node("a.example.net"),b=node("b.example.net"),c=node("c.example.net");a.exit=b;Gateway next=PairNodes.copy(b);next.exit=PairNodes.copy(c);ArrayList<Gateway> records=new ArrayList<>(Arrays.asList(a,c));PairNodes.attach(records,next);assertEquals(2,records.size());assertNotNull(PairNodes.find(records,a.get("id")));assertFalse(PairNodes.find(records,a.get("id")).isPair());assertEquals(3,PairNodes.catalog(records).size());}
 @Test public void aRoleSwapAlwaysRemovesTheOldEntryFirst()throws Exception{JSONObject review=new JSONObject().put("entry",new JSONObject().put("kind","pair").put("role","exit")).put("exit",new JSONObject().put("kind","pair").put("role","entry"));assertEquals(Arrays.asList("exit","entry"),PairPreparationController.order(review));assertTrue(PairPreparationController.removalNeeded(review));}
 @Test public void freshSavedServersDoNotNeedDestructiveConsent()throws Exception{JSONObject fresh=new JSONObject().put("kind","fresh");assertFalse(PairPreparationController.removalNeeded(new JSONObject().put("entry",fresh).put("exit",fresh)));}
 @Test public void everyEntryAndExitCombinationUsesTheReviewedProtocolAndPort()throws Exception{for(SingleProtocols entry:SingleProtocols.values())for(SingleProtocols exit:SingleProtocols.values()){Gateway a=node("entry.example.net");a.exit=node("exit.example.net");a.set("pairId",PairController.newId());a.set("pairEntryProtocol",entry.id);a.set("pairExitProtocol",exit.id);JSONObject request=PairController.request(a,"entry");assertEquals(entry.id,request.getString("entry_protocol"));assertEquals(exit.id,request.getString("exit_protocol"));assertEquals(entry.port,request.getInt("vpn_port"));assertEquals(!(entry==SingleProtocols.IKEV2&&exit==SingleProtocols.AWG),PairController.modern(a));}}
 @Test public void anEmptyManagedServerDoesNotBecomeAnIkeProfile()throws Exception{Gateway a=node("empty.example.net");a.set("protocol","");assertNull(ServerProtocols.find(Arrays.asList(a),a,"ikev2"));assertTrue(ServerProtocols.installed(Arrays.asList(a),a).isEmpty());}
 @org.junit.Test public void swappingDraftRolesKeepsAccessWithTheMachineAndReversesTheRelay(){PairSetupState d=new PairSetupState();d.entry="openvpn";d.exit="xray";d.put("entrySaved","A");d.put("exitSaved","B");d.put("entryPassword","a-fixture");d.put("exitPassword","b-fixture");d.put("relay","entry-via-exit");d.swapServers();org.junit.Assert.assertEquals("B",d.get("entrySaved",""));org.junit.Assert.assertEquals("b-fixture",d.get("entryPassword",""));org.junit.Assert.assertEquals("A",d.get("exitSaved",""));org.junit.Assert.assertEquals("a-fixture",d.get("exitPassword",""));org.junit.Assert.assertEquals("exit-via-entry",d.get("relay",""));org.junit.Assert.assertEquals("openvpn",d.entry);org.junit.Assert.assertEquals("xray",d.exit);}
 @Test public void removingPairSetupClearsItsFavoriteButPreservesServerAccess()throws Exception{Gateway n=node("entry.example.net");n.set("protocol","awg");n.data.put("favorite",true);n.data.put("snapshot",new JSONObject().put("services",new JSONObject()));PairNodes.clearConnection(n);assertFalse(n.data.optBoolean("favorite"));assertTrue(n.get("protocol").isEmpty());assertEquals("entry.example.net",n.get("host"));assertEquals("fixture-password",n.sshPassword);assertEquals("SHA256:fixture",n.get("fingerprint"));}
 @Test public void pairHealthRetainsEachMembersOwnInstallationIdentity()throws Exception{Gateway pair=node("entry.example.net");pair.exit=node("exit.example.net");JSONObject entry=new JSONObject().put("instance","entry-generation"),exit=new JSONObject().put("instance","public-exit-generation");assertTrue(PairNodes.rememberHealth(pair,new JSONObject().put("entry",entry).put("exit",exit)).isEmpty());assertEquals("entry-generation",pair.get("serverInstance"));assertEquals("public-exit-generation",pair.exit.get("serverInstance"));Gateway reopened=new Gateway(pair.persisted());assertEquals("entry-generation",reopened.get("serverInstance"));assertEquals("public-exit-generation",reopened.exit.get("serverInstance"));assertSame(entry,pair.data.getJSONObject("snapshot"));assertSame(exit,pair.exit.data.getJSONObject("snapshot"));}
 @Test public void pairHealthReportsOnlyTheMemberWhoseKnownIdentityChanged()throws Exception{Gateway pair=node("entry.example.net");pair.exit=node("exit.example.net");pair.set("serverInstance","entry-old");pair.exit.set("serverInstance","exit-stable");JSONObject result=new JSONObject().put("entry",new JSONObject().put("instance","entry-new")).put("exit",new JSONObject().put("instance","exit-stable"));assertEquals(Collections.singletonList(pair),PairNodes.rememberHealth(pair,result));assertTrue(PairNodes.rememberHealth(pair,result).isEmpty());result.getJSONObject("exit").put("instance","exit-new");assertEquals(Collections.singletonList(pair.exit),PairNodes.rememberHealth(pair,result));}
 @Test public void missingPairHealthIdentityNeverErasesOrCopiesTheOtherMembersIdentity()throws Exception{Gateway pair=node("entry.example.net");pair.exit=node("exit.example.net");pair.set("serverInstance","entry-known");pair.exit.set("serverInstance","exit-known");assertTrue(PairNodes.rememberHealth(pair,new JSONObject().put("entry",new JSONObject()).put("exit",new JSONObject().put("instance",""))).isEmpty());assertEquals("entry-known",pair.get("serverInstance"));assertEquals("exit-known",pair.exit.get("serverInstance"));pair.exit.set("serverInstance","");PairNodes.rememberHealth(pair,new JSONObject().put("entry",new JSONObject().put("instance","entry-known")).put("exit",new JSONObject()));assertEquals("",pair.exit.get("serverInstance"));}
 @Test public void malformedPairHealthCannotPartiallyAdvanceAnIdentity()throws Exception{Gateway pair=node("entry.example.net");pair.exit=node("exit.example.net");pair.set("serverInstance","entry-old");try{PairNodes.rememberHealth(pair,new JSONObject().put("entry",new JSONObject().put("instance","entry-new")).put("exit",new JSONObject().put("instance",new JSONArray())));fail("Malformed identity accepted");}catch(JSONException expected){}assertEquals("entry-old",pair.get("serverInstance"));assertFalse(pair.data.has("snapshot"));}

 private void pendingResetWork(Gateway n)throws Exception{
  for(String key:new String[]{"lifecycleOperation","entryMigration","pairedOsOperation","helperUpdate","engineUpdate"})n.data.put(key,new JSONObject().put("state","preparing").put("operation","retained-failed-operation"));
  n.set("job","old-job");n.set("jobKind","pair");n.set("jobPhase","Starting");n.set("setupIntent","install");n.data.put("pairNeedsPreparation",true).put("deploymentInventory",new JSONObject()).put("deploymentRevision",4);
 }
 @Test public void confirmedEmptyResetRetiresPendingWorkButKeepsAccessAndTerminalHistory()throws Exception{
  Gateway n=node("entry.example.net"),previous=node("old.example.net"),candidate=node("candidate.example.net");previous.exit=node("old-exit.example.net");
  for(Gateway item:Arrays.asList(n,previous,previous.exit,candidate))pendingResetWork(item);
  n.privateKey="retained-key";n.data.put("port",2222).put("saveAccessChosen",true);n.set("adminServerId","retained-authority");n.set("serverName","Family server");n.set("osReinstallState","complete");
  JSONObject os=new JSONObject().put("job","completed-os-job").put("fingerprint",n.get("fingerprint")),restored=new JSONObject().put("phase","restored").put("operation","historical-os-operation"),activity=new JSONObject().put("lifecycleOperation","unrelated opaque note");
  n.data.put("osReinstall",os).put("lastPairedOsOperation",restored).put("activityHistory",activity).put("lastHelperUpdate",new JSONObject().put("state","accepted"));
  n.data.put("lastLifecycleOperation",new JSONObject().put("state","rolled-back").put("operation","completed-move").put("previous",previous.persisted()).put("candidate",candidate.persisted()));
  JSONObject acknowledgement=new JSONObject().put("reset",true).put("already_empty",true).put("os_reinstall",false);
  PairNodes.clearAfterConfirmedReset(n,acknowledgement,false);Gateway saved=new Gateway(n.persisted());
  for(String key:new String[]{"lifecycleOperation","entryMigration","pairedOsOperation","helperUpdate","engineUpdate","job","jobKind","jobPhase","setupIntent","pairNeedsPreparation","deploymentInventory","deploymentRevision"})assertFalse(key,saved.data.has(key));
  JSONObject history=saved.data.getJSONObject("lastLifecycleOperation");assertEquals("rolled-back",history.getString("state"));assertEquals("completed-move",history.getString("operation"));
  for(JSONObject snapshot:Arrays.asList(history.getJSONObject("previous"),history.getJSONObject("previous").getJSONObject("pairExit"),history.getJSONObject("candidate")))for(String key:new String[]{"lifecycleOperation","entryMigration","pairedOsOperation","helperUpdate","engineUpdate","job"})assertFalse(key,snapshot.has(key));
  assertEquals(restored.toString(),saved.data.getJSONObject("lastPairedOsOperation").toString());assertEquals(os.toString(),saved.data.getJSONObject("osReinstall").toString());assertEquals(activity.toString(),saved.data.getJSONObject("activityHistory").toString());assertEquals("accepted",saved.data.getJSONObject("lastHelperUpdate").getString("state"));
  assertEquals(n.get("id"),saved.get("id"));assertEquals("entry.example.net",saved.get("host"));assertEquals("root",saved.get("admin"));assertEquals("SHA256:fixture",saved.get("fingerprint"));assertEquals(n.get("machine"),saved.get("machine"));assertEquals(2222,saved.port());assertEquals("fixture-password",saved.sshPassword);assertEquals("retained-key",saved.privateKey);assertTrue(saved.remember());assertTrue(saved.data.getBoolean("saveAccessChosen"));assertEquals("retained-authority",saved.get("adminServerId"));assertEquals("Family server",saved.get("serverName"));
  String once=n.persisted().toString();PairNodes.clearAfterConfirmedReset(n,acknowledgement,false);assertEquals(once,n.persisted().toString());
 }
 @Test public void plansFailuresAndActivePhoneOrOsWorkCannotClearPendingMetadata()throws Exception{
  Gateway n=node("entry.example.net");pendingResetWork(n);
  for(JSONObject result:Arrays.asList(null,new JSONObject(),new JSONObject().put("already_empty",true),new JSONObject().put("reset",false),new JSONObject().put("reset","true"),new JSONObject().put("reset",true).put("os_reinstall",true))){String before=n.persisted().toString();try{PairNodes.clearAfterConfirmedReset(n,result,false);fail("Unconfirmed reset cleared metadata");}catch(java.io.IOException expected){}assertEquals(before,n.persisted().toString());}
  JSONObject confirmed=new JSONObject().put("reset",true);String before=n.persisted().toString();try{PairNodes.clearAfterConfirmedReset(n,confirmed,true);fail("Active coordinator was cleared");}catch(java.io.IOException expected){}assertEquals(before,n.persisted().toString());
  n.set("osReinstallState","rebooting");before=n.persisted().toString();try{PairNodes.clearAfterConfirmedReset(n,confirmed,false);fail("Active OS work was cleared");}catch(java.io.IOException expected){}assertEquals(before,n.persisted().toString());
  for(String field:new String[]{"clientOnly","adminAccess"}){Gateway client=node("entry.example.net");pendingResetWork(client);client.data.put(field,true);before=client.persisted().toString();try{PairNodes.clearAfterConfirmedReset(client,confirmed,false);fail("Nonowner record was cleared");}catch(java.io.IOException expected){}assertEquals(before,client.persisted().toString());}
 }
 @Test public void ordinaryConnectionClearingDoesNotPretendToConfirmARemoteReset()throws Exception{
  Gateway n=node("draft.example.net");pendingResetWork(n);PairNodes.clearConnection(n);
  for(String key:new String[]{"lifecycleOperation","entryMigration","pairedOsOperation","helperUpdate","engineUpdate"})assertEquals("preparing",n.data.getJSONObject(key).getString("state"));
 }

}
